def find_good_numbers(n_small):
    good_numbers = set()
    for x in range(1, 100):
        for y in range(x + 1, 100):
            import math
            if math.gcd(x, y) > 1:
                good_numbers.add(x*x + y*y)

    sorted_good = sorted(list(good_numbers))
    return sorted_good

